// The corpus behind `grimoire/cli-golden.test.ts`. Three layers per spell:
//
//   1. GENERATED by the ward (not listed here): the root tokens (bare, --help,
//      -h, help, --version, -V, version, schema), an unknown root flag, an
//      unknown verb, `-- --x`, `version --bogus`, and for EVERY verb the CLI's
//      own rejection `choices` name: `<verb> --acc-bogus-flag` and `<verb> --help`.
//   2. HAND-WRITTEN below: each verb with its documented flags, flags before
//      the verb, `--flag=value`, repeated flags, and the `--` terminator cases.
//   3. DOCUMENTED: every invocation the spell's SKILL.md shows, extracted to
//      `grimoire/fixtures/cli-golden/documented/<spell>.json` with its line.
//
// An EXCLUDED verb starts a daemon, opens a browser, streams forever, or reads
// the machine's process table; it is run only as layer 1's two rejection-shaped
// cases, and any documented invocation of it is listed, not run.
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { Case, SpellSpec } from "./cli-golden";

const c = (...argv: string[]): Case => ({ argv });
const stdin = (text: string, ...argv: string[]): Case => ({ argv, stdin: text });
const stub = (...argv: string[]): Case => ({ argv, stub: true });

const SPAWNS = "starts a daemon (and may open a browser)";
const STREAMS = "a long-running stream (tail); never ends on its own within the run";

